  ('국제사법재판소(ICJ)의 재판관 수는?', '["7명","9명","15명","21명"]'::jsonb, 2, 'ICJ 재판관은 15명이에요.', 5, '국제연합(UN)', 'https://www.un.org'),
  ('세계무역기구(WTO)에서 무역분쟁의 최종 판단을 다루는 기구는?', '["총회","사무국","안보리","상소기구"]'::jsonb, 3, 'WTO 상소기구가 최종 판단을 맡아요.', 5, '국제연합(UN)', 'https://www.un.org'),
  ('해양의 경계·자원을 규율하는 UN 협약의 약칭은?', '["NATO","UNCLOS","GATT","NPT"]'::jsonb, 1, 'UNCLOS는 유엔해양법협약이에요.', 5, '국제연합(UN)', 'https://www.un.org'),
  ('연안국의 배타적경제수역(EEZ)은 기선에서 몇 해리까지인가?', '["12해리","200해리","24해리","350해리"]'::jsonb, 1, 'EEZ는 기선에서 200해리까지예요.', 5, '국제연합(UN)', 'https://www.un.org'),
  ('국가의 요건(국민·영토·정부·주권)을 규정한 1933년 협약은?', '["제네바 협약","헤이그 협약","빈 협약","몬테비데오 협약"]'::jsonb, 3, '몬테비데오 협약이 국가 요건을 규정해요.', 5, '국제연합(UN)', 'https://www.un.org')
)
insert into public.questions (
  category, prompt, choices, answer_index, explanation, difficulty,
  source_name, source_url, fact_checked_at, expires_at, status,
  ai_generated, content_hash, reviewed_by
)
select
  'world', prompt, choices, answer_index, explanation, difficulty,
  source_name, source_url, now(), now() + interval '365 days', 'approved',
  false, encode(digest(prompt, 'sha256'), 'hex'), 'mvp-seed'
from seed
on conflict (content_hash) do update set
  category = excluded.category,
  choices = excluded.choices,
  answer_index = excluded.answer_index,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  status = 'approved',
  expires_at = excluded.expires_at,
  fact_checked_at = excluded.fact_checked_at;

select difficulty, count(*) from public.questions
where category='world' and status='approved' group by difficulty order by difficulty;
